const catalog = new Map(ENCOUNTERS.map(scene=>[scene.key,scene]));
export function encounterKey(attacker,defender){
 if(typeof attacker!=='string'||typeof defender!=='string'||attacker.length!==2||defender.length!==2||attacker[0]===defender[0]||!['r','b'].includes(attacker[0])||!['r','b'].includes(defender[0]))return null;
 const red=attacker[0]==='r'?attacker:defender,black=attacker[0]==='b'?attacker:defender;
 return 'r'+red[1]+'-b'+black[1];
}
export function getBattleScene(attacker,defender){return catalog.get(encounterKey(attacker,defender))||null;}
export function getSceneByKey(key){return catalog.get(key)||null;}
export function filterScenes(red='',black=''){return ENCOUNTERS.filter(scene=>(!red||scene.red===red)&&(!black||scene.black===black));}
